<?php ob_start(); ?><h1><?= e(t('Finding #:id', ['id'=>$finding['id'] ?? ''])) ?></h1><?php if(!$finding): ?><p><?= e(t('Not found.')) ?></p><?php else: ?><div class="card"><p><b><?= e(t('Path:')) ?></b> <code><?= e($finding['path']) ?></code></p><p><b><?= e(t('Risk:')) ?></b> <span class="badge <?= e($finding['risk']) ?>"><?= e(t($finding['risk'])) ?></span> <b><?= e(t('Type:')) ?></b> <?= e($finding['type']) ?> <b><?= e(t('Status:')) ?></b> <?= e(t($finding['status'])) ?></p><p><b>SHA256:</b> <code><?= e($finding['sha256']) ?></code></p><p><b><?= e(t('Size:')) ?></b> <?= e($finding['size']) ?> <b>mtime:</b> <?= e($finding['mtime']) ?> <b><?= e(t('owner:')) ?></b> <?= e($finding['owner']) ?> <b><?= e(t('permissions:')) ?></b> <?= e($finding['permissions']) ?></p><p><b><?= e(t('Matched signature:')) ?></b> <?= e($finding['matched_signature_name'] ?? '') ?> <?= e($finding['last_matched_signature_id'] ?? '') ?> <?= e($finding['matched_signature_source'] ?? '') ?></p><p><b><?= e(t('Match details:')) ?></b></p><pre><?= e(json_encode(json_decode($finding['signature_match_details'] ?: '{}', true), JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)) ?></pre><p><b><?= e(t('Matched rules:')) ?></b></p><pre><?= e(json_encode(json_decode($finding['matched_rules'] ?: '[]', true), JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)) ?></pre><form method="post" action="/finding/signature-suggest" style="display:inline" onsubmit="return confirm(<?= e(json_encode(t('Snippets/metadata may be sent to the configured AI provider if AI signatures are enabled. Continue?'))) ?>)"><input type="hidden" name="id" value="<?= e($finding['id']) ?>"><button class="btn"><?= e(t('Generate signature with AI')) ?></button></form> <form method="post" action="/finding/create-signature" style="display:inline"><input type="hidden" name="id" value="<?= e($finding['id']) ?>"><button class="btn"><?= e(t('Create signature from this finding')) ?></button></form> <a class="btn" href="/signatures?file=<?= urlencode($finding['path']) ?>"><?= e(t('Test existing signatures against this file')) ?></a> <form method="post" action="/finding/ignore" style="display:inline"><input type="hidden" name="id" value="<?= e($finding['id']) ?>"><button class="btn"><?= e(t('Ignore')) ?></button></form> <form method="post" action="/finding/allowlist" style="display:inline"><input type="hidden" name="id" value="<?= e($finding['id']) ?>"><button class="btn"><?= e(t('Allowlist')) ?></button></form><p><a class="btn" href="/backups?path=<?= urlencode($finding['path']) ?>"><?= e(t('Find in backup')) ?></a> <a class="btn" href="/backups?path=<?= urlencode($finding['path']) ?>"><?= e(t('Preview backup version / Diff with backup / Restore this file from backup')) ?></a></p><?php if(config('guard.web_actions_enabled')): ?> <form method="post" action="/finding/quarantine" onsubmit="return confirm(<?= e(json_encode(t('Move file to quarantine?'))) ?>)" style="display:inline"><input type="hidden" name="id" value="<?= e($finding['id']) ?>"><button class="btn danger"><?= e(t('Quarantine')) ?></button></form><?php else: ?><p><?= e(t('Web actions disabled. Use CLI:')) ?> <code>php artisan guard:quarantine <?= e($finding['id']) ?></code></p><?php endif ?></div><div class="card"><h2><?= e(t('Safe preview')) ?></h2><pre><?= e($preview ?: t('Preview unavailable or empty.')) ?></pre></div><div class="card"><h2><?= e(t('Related log events')) ?></h2><table><tr><th><?= e(t('Risk')) ?></th><th><?= e(t('IP')) ?></th><th><?= e(t('URI')) ?></th><th><?= e(t('Raw')) ?></th></tr><?php foreach($events as $l): ?><tr><td><?= e(t($l['risk'])) ?></td><td><?= e($l['ip']) ?></td><td><?= e($l['uri']) ?></td><td><?= e($l['raw_line']) ?></td></tr><?php endforeach ?></table></div><?php endif ?><?php $content=ob_get_clean(); include base_path('resources/views/layouts/app.php'); ?>
